<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0f766e"><title>{{ $campaign->headline }}</title><script src="https://cdn.tailwindcss.com"></script><style>.step{display:none}.step.active{display:block;animation:enter .25s ease-out}@keyframes enter{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}.choice.selected{border-color:#0f766e;background:#f0fdfa;box-shadow:0 0 0 3px rgba(13,148,136,.1)}.choice.selected .dot{background:#0f766e;border-color:#0f766e;box-shadow:inset 0 0 0 4px white}</style></head><body class="min-h-screen bg-[#f3fbfa] text-slate-950"><div class="min-h-screen lg:grid lg:grid-cols-[.9fr_1.1fr]"><aside class="hidden bg-teal-900 p-12 text-white lg:flex lg:flex-col lg:justify-between"><div><div class="grid h-11 w-11 place-items-center rounded-2xl bg-white text-sm font-black text-teal-800">{{ strtoupper(substr($campaign->name,0,1)) }}</div><div class="mt-24 max-w-lg"><p class="text-sm font-black uppercase tracking-[.22em] text-teal-300">{{ $campaign->name }}</p><h1 class="mt-5 text-5xl font-black leading-tight">{{ $campaign->headline }}</h1><p class="mt-6 text-lg leading-8 text-teal-100/80">{{ $campaign->description ?: 'Tell us a little about yourself. It takes just a minute.' }}</p><div class="mt-10 rounded-2xl border border-white/10 bg-white/5 p-5"><b>Quick application</b><p class="mt-1 text-sm text-teal-100/70">{{ count($campaign->configuredQuestions()) + 3 }} short questions. No account required.</p></div></div></div><p class="text-xs text-teal-200/60">Powered by LAMI AI</p></aside><main class="flex min-h-screen items-center justify-center px-5 py-7 sm:px-8"><div class="w-full max-w-xl"><div class="mb-6 flex items-center justify-between lg:hidden"><div class="font-black text-teal-800">{{ $campaign->name }}</div><span class="text-xs font-bold text-slate-400">Quick application</span></div><div class="mb-8"><div class="flex justify-between text-xs font-black uppercase tracking-wider text-slate-400"><span id="label">Step 1</span><span id="pct">0%</span></div><div class="mt-3 h-1.5 overflow-hidden rounded-full bg-teal-100"><div id="bar" class="h-full rounded-full bg-teal-600 transition-all" style="width:0"></div></div></div><form id="f" method="POST" action="{{ route('marketing.campaign.submit',$campaign) }}" novalidate>@csrf<input name="website" class="hidden" tabindex="-1" autocomplete="off">@foreach(['utm_source','utm_medium','utm_campaign','utm_content','utm_term'] as $u)<input type="hidden" name="{{ $u }}" value="{{ request($u) }}">@endforeach
