@foreach($questions as $index => $q)<section class="step" data-n="{{ $index + 3 }}"><span class="text-sm font-black text-teal-700">Question {{ $index + 1 }}</span><h2 class="mt-3 text-3xl font-black sm:text-4xl">{{ $q['label'] }}</h2>@if($q['type']==='single_choice')<div class="mt-8 grid gap-3">@foreach($q['options'] as $option)<button type="button" data-name="q_{{ $q['id'] }}" data-value="{{ $option }}" class="choice flex items-center justify-between rounded-2xl border-2 border-slate-200 bg-white p-5 text-left"><span><b class="text-lg">{{ $option }}</b></span><i class="dot h-6 w-6 rounded-full border-2 border-slate-300"></i></button>@endforeach</div><input type="hidden" name="q_{{ $q['id'] }}" @if($q['required']) data-choice-required="1" @endif>@else<input @if($q['required']) required data-req @endif type="{{ $q['type']==='email'?'email':($q['type']==='phone'?'tel':'text') }}" name="q_{{ $q['id'] }}" placeholder="Your answer" class="mt-8 w-full rounded-2xl border-slate-200 bg-white px-5 py-4 text-lg focus:border-teal-600 focus:ring-teal-100">@endif</section>@endforeach
<div id="err" class="mt-4 hidden rounded-xl bg-red-50 px-4 py-3 text-sm font-bold text-red-700"></div><div class="mt-8 flex justify-between gap-3"><button type="button" id="back" class="rounded-xl px-4 py-3 font-bold text-slate-500">← Back</button><button type="button" id="next" class="rounded-xl bg-teal-700 px-6 py-3.5 font-black text-white">Next →</button><button type="submit" id="submit" class="hidden rounded-xl bg-teal-700 px-6 py-3.5 font-black text-white">Submit application</button></div></form><p class="mt-8 text-center text-xs text-slate-400">Your details are used by {{ $campaign->name }} to follow up on this campaign.</p></div></main></div><script>(()=>{let i=0,s=[...document.querySelectorAll('.step')],total=s.length,f=document.getElementById('f'),n=document.getElementById('next'),b=document.getElementById('back'),sub=document.getElementById('submit'),e=document.getElementById('err');function u(){s.forEach((x,j)=>x.classList.toggle('active',j===i));let p=Math.round((i+1)/total*100);document.getElementById('label').textContent=`Step ${i+1} of ${total}`;document.getElementById('pct').textContent=p+'%';document.getElementById('bar').style.width=p+'%';b.classList.toggle('invisible',i===0);n.classList.toggle('hidden',i===total-1);sub.classList.toggle('hidden',i!==total-1);e.classList.add('hidden')}function v(){let x=s[i].querySelector('[data-req]');if(x&&(!x.value.trim()||(x.type==='email'&&!x.checkValidity()))){e.textContent=x.type==='email'?'Please enter a valid email address.':'Please answer this question before continuing.';e.classList.remove('hidden');x.focus();return false}let c=s[i].querySelector('[data-choice-required]');if(c&&!c.value){e.textContent='Please choose one option.';e.classList.remove('hidden');return false}return true}document.querySelectorAll('[data-name]').forEach(x=>x.onclick=()=>{let z=x.dataset.name;f.querySelector('[name="'+z+'"]').value=x.dataset.value;document.querySelectorAll('[data-name="'+z+'"]').forEach(y=>y.classList.remove('selected'));x.classList.add('selected');e.classList.add('hidden');if(s[i].querySelector('[data-choice-required]')){setTimeout(()=>{if(i<total-1){i++;u()}},180)}});n.onclick=()=>{if(v()){i++;u()}};b.onclick=()=>{if(i){i--;u()}};f.onsubmit=x=>{if(!v())x.preventDefault();else{sub.disabled=true;sub.textContent='Submitting...'}};u()})()</script></body></html>
